import{nearestBassSample}from'./bass.js';
import{loadKit,audioBuffers}from'./kit.js';
import{secondsAt,tempoMap}from'./engine.js';
export class Player{
 constructor(){this.ctx=null;this.timer=null;this.onProgress=null;this.onEnd=null}
 stop(){clearInterval(this.timer);this.timer=null;if(this.ctx){this.ctx.close().catch(()=>{});this.ctx=null}this.onProgress?.(0)}
 async play(song,result,override,reference,parts={drums:true,bass:true}){this.stop();const AC=globalThis.AudioContext||globalThis.webkitAudioContext;if(!AC)throw Error('This browser does not support Web Audio. Download MIDI to listen in your DAW.');const ctx=new AC();this.ctx=ctx;await ctx.resume();if(this.ctx!==ctx)return;const kit=await loadKit();if(this.ctx!==ctx)return;const buffers=audioBuffers(ctx,kit);const master=ctx.createGain();master.gain.value=.8;const comp=ctx.createDynamicsCompressor();master.connect(comp);comp.connect(ctx.destination);const map=tempoMap(song,override),total=result.events.reduce((end,e)=>Math.max(end,secondsAt(e.beat,map)+(buffers[e.note]?.duration||0)),secondsAt(song.length,map)),start=ctx.currentTime+.08;let index=0;const events=(parts.drums?result.events:[]).map(e=>({...e,time:secondsAt(e.beat,map)}));if(parts.bass)for(const e of result.bassEvents||[])events.push({...e,bass:true,time:secondsAt(e.beat,map),duration:secondsAt(e.beat+e.duration,map)-secondsAt(e.beat,map)});if(reference)for(const b of song.bars)for(const h of b.hits)for(const pitch of h.pitches.slice(0,3))events.push({time:secondsAt(b.start+h.t,map),pitch,duration:Math.min(.35,Math.max(.06,h.duration*60/(override||song.bpm)))});events.sort((a,b)=>a.time-b.time);
 const tick=()=>{if(this.ctx!==ctx)return;const elapsed=ctx.currentTime-start;while(index<events.length&&events[index].time<elapsed+.18){const e=events[index++],time=Math.max(ctx.currentTime,start+e.time);if(e.bass)this.bass(ctx,master,buffers,time,e.note,e.velocity,e.duration);else if(e.pitch!==undefined)this.guitar(ctx,master,time,e.pitch,e.duration);else this.drum(ctx,master,buffers,time,e.note,e.velocity)}this.onProgress?.(Math.max(0,Math.min(1,elapsed/total)));if(elapsed>total+.8){this.stop();this.onEnd?.()}};tick();this.timer=setInterval(tick,25);
 }
 drum(ctx,out,buffers,t,n,v){const buffer=buffers[n];if(!buffer)return;const source=ctx.createBufferSource(),gain=ctx.createGain();source.buffer=buffer;gain.gain.value=2*(v/127)**1.3;source.connect(gain);gain.connect(out);source.start(t);}
 bass(ctx,out,buffers,t,note,velocity,duration){const source=ctx.createBufferSource(),gain=ctx.createGain();source.buffer=buffers['bass-'+nearestBassSample(note)];source.playbackRate.value=2**((note-nearestBassSample(note))/12);const volume=1.65*(velocity/127)**1.3;gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(volume,t+.006);gain.gain.setValueAtTime(volume,t+duration);gain.gain.linearRampToValueAtTime(0,t+duration+.06);source.connect(gain);gain.connect(out);source.start(t);source.stop(t+duration+.065);}
 guitar(ctx,out,t,pitch,duration){const osc=ctx.createOscillator(),filter=ctx.createBiquadFilter(),g=ctx.createGain();osc.type='sawtooth';osc.frequency.value=440*2**((pitch-69)/12);filter.type='lowpass';filter.frequency.setValueAtTime(2400,t);filter.frequency.exponentialRampToValueAtTime(500,t+duration);g.gain.setValueAtTime(.065,t);g.gain.exponentialRampToValueAtTime(.001,t+duration);osc.connect(filter);filter.connect(g);g.connect(out);osc.start(t);osc.stop(t+duration+.02)}
}
